<script setup lang="ts">
import {computed,onBeforeUnmount,ref,shallowRef,watch} from 'vue'
import {ApiError,onIdentityChange} from '@/core/http'
import RulePreprocessOperationTable from './RulePreprocessOperationTable.vue'
import RulePreprocessFunctionDialog from './RulePreprocessFunctionDialog.vue'
import RuleFunctionCodeEditor from './RuleFunctionCodeEditor.vue'
import ReferenceIcon from '@/ui/ReferenceIcon.vue'
import {WarningFilled} from '@element-plus/icons-vue'
import RuleCoordinateTransformDialog from './RuleCoordinateTransformDialog.vue'
import RuleGeofenceDialog from './RuleGeofenceDialog.vue'
import RulePeriodUsageDialog from './RulePeriodUsageDialog.vue'
import type {PeriodUsageDraft} from './period-usage-draft'
import type {GeofenceKind,GeofenceDraft,CircleGeofenceDraft,PolygonGeofenceDraft} from './geofence-draft'
import {clonePropertyOperations,functionsToPropertyOperations,propertyOperationsDraft,type PropertyOperationDraft,type PropertyOperationsDraft,type PropertyOperationCommand} from './property-operations-draft'
import type {CoordinateTransformDraft} from './coordinate-transform-draft'
import type {RuleSourceInput} from './rule-source-selection'
import type {RuleDeviceSourceContract} from './rule-source-api'
import {newFunction,dataReportFunctionSource,type FunctionDraft,type PreprocessKind} from './rule-builder-draft'
const props=defineProps<{modelValue:FunctionDraft[];disabled?:boolean;dataReport?:boolean;dataFormat?:string;hideAdd?:boolean;kind?:PreprocessKind;projectId?:string;scopeKey?:string;source?:RuleSourceInput|RuleDeviceSourceContract;propertyOperations?:PropertyOperationsDraft;detail?:boolean;command?:PropertyOperationCommand;requestError?:string;recoveryPending?:boolean;recovering?:boolean}>()
const placeholder=computed(()=>props.dataReport?dataReportFunctionSource:'module.exports = attributes => attributes;')
const emit=defineEmits<{'update:modelValue':[value:FunctionDraft[]];'update:propertyOperations':[value:PropertyOperationsDraft];busy:[value:boolean];commit:[];cancelCommand:[];recover:[];denied:[cause:ApiError]}>()
const removal=ref<string>()
const pickerShown=ref(false),selectedGeofence=shallowRef<{id:string;kind:GeofenceKind;config:GeofenceDraft}>()
const selectedPeriod=shallowRef<{id:string;config:PeriodUsageDraft}>()
const selectedCoordinate=shallowRef<{id:string;config:CoordinateTransformDraft}>(),rows=computed(()=>props.propertyOperations?.operations??props.modelValue),coordinateAvailable=computed(()=>props.kind==='ATTRS_RPT_PREPROC'&&!!props.projectId&&!!props.source&&!props.dataReport)
const selected=shallowRef<FunctionDraft>(),sorting=ref(false),unavailable=ref(false),tableError=ref('')
const sourceLimit=computed(()=>Math.max(0,65536-rows.value.filter(row=>row.id!==selected.value?.id).reduce((sum,row)=>sum+new TextEncoder().encode('kind' in row?(row.kind==='FUNCTION'?row.function.source:''):row.source).length,0)))
watch(()=>props.scopeKey,()=>{selected.value=undefined;selectedCoordinate.value=undefined;selectedGeofence.value=undefined;selectedPeriod.value=undefined;pickerShown.value=false;removal.value=undefined;sorting.value=false;unavailable.value=false;tableError.value=''})
const formatting=ref<ReadonlySet<string>>(new Set()),busy=computed(()=>formatting.value.size>0||!!selected.value||!!selectedCoordinate.value||!!selectedGeofence.value||!!selectedPeriod.value||pickerShown.value||!!removal.value||sorting.value),blocked=computed(()=>props.disabled||busy.value||unavailable.value)
function formatBusy(id:string,value:boolean){const next=new Set(formatting.value);if(value)next.add(id);else next.delete(id);formatting.value=next}
watch(busy,value=>emit('busy',value),{immediate:true,flush:'sync'})
watch(()=>props.modelValue.map(row=>row.id),ids=>{formatting.value=new Set([...formatting.value].filter(id=>ids.includes(id)))})
const dispose=onIdentityChange(()=>{selected.value=undefined;selectedCoordinate.value=undefined;selectedGeofence.value=undefined;selectedPeriod.value=undefined;pickerShown.value=false;removal.value=undefined;sorting.value=false;unavailable.value=true;tableError.value='身份已变化，请重新读取规则。'})
onBeforeUnmount(()=>{selected.value=undefined;selectedCoordinate.value=undefined;selectedGeofence.value=undefined;selectedPeriod.value=undefined;pickerShown.value=false;emit('busy',false);dispose()})
const bytes=computed(()=>props.modelValue.reduce((sum,row)=>sum+new TextEncoder().encode(row.source).length,0))
function setFormat(id:string,format:string){const index=props.modelValue.findIndex(row=>row.id===id);if(index>=0)update(index,{format:format as FunctionDraft['format']})}
function update(index:number,patch:Partial<FunctionDraft>){if(!props.disabled)emit('update:modelValue',props.modelValue.map((row,i)=>i===index?{...row,...patch}:row))}
function move(index:number,direction:-1|1){
 if(blocked.value||index+direction<0||index+direction>=props.modelValue.length)return
 const values=[...props.modelValue];[values[index],values[index+direction]]=[values[index+direction]!,values[index]!];emit('update:modelValue',values)
}
function add(){if(!blocked.value&&props.modelValue.length<(props.dataReport?1:32))emit('update:modelValue',[...props.modelValue,{...newFunction(),source:props.dataReport?dataReportFunctionSource:''}])}
function remove(id:string){if(blocked.value)return;if(props.detail){removal.value=id;tableError.value='';return;}if(props.propertyOperations)commitOperations(props.propertyOperations.operations.filter(row=>row.id!==id));else emit('update:modelValue',props.modelValue.filter(row=>row.id!==id))}
function open(id?:string){
 if(blocked.value)return
 const existing=id?rows.value.find(row=>row.id===id):undefined;if(id&&!existing||!existing&&rows.value.length>=32)return
 if(existing&&'kind' in existing&&existing.kind==='PERIOD_USAGE'){selectedPeriod.value={id:existing.id,config:{...existing.config}};tableError.value='';return}
 if(existing&&'kind' in existing&&(existing.kind==='POINT_IN_CIRCLE'||existing.kind==='POINT_IN_POLYGON')){selectedGeofence.value={id:existing.id,kind:existing.kind,config:{...existing.config}};tableError.value='';return}
 if(existing&&'kind' in existing&&existing.kind==='COORDINATE_TRANSFORM'){selectedCoordinate.value={id:existing.id,config:{...existing.config}};tableError.value='';return}
 selected.value=existing?'kind' in existing?{id:existing.id,...existing.function}:{...existing}:{...newFunction(),format:'COMMON_JS',source:''};tableError.value=''
}
function addOperation(){if(blocked.value)return;if(coordinateAvailable.value||props.detail||props.kind==='ATTRS_PUSH_PREPROC')pickerShown.value=true;else open()}
function closePicker(){if(!props.disabled){pickerShown.value=false;if(props.detail)emit('cancelCommand')}}
function chooseOperation(kind:PropertyOperationDraft['kind']){if(props.disabled||unavailable.value||!pickerShown.value)return;pickerShown.value=false;if(kind==='FUNCTION')open();else if(kind==='COORDINATE_TRANSFORM')openCoordinate();else if(kind==='PERIOD_USAGE')openPeriod();else openGeofence(kind)}
function openCoordinate(){if(blocked.value||!coordinateAvailable.value||rows.value.length>=32)return;selectedCoordinate.value={id:newFunction().id,config:{inputProperty:'',conversion:'WGS84_TO_GCJ02',outputProperty:''}};tableError.value=''}
function openPeriod(){if(blocked.value||!coordinateAvailable.value||rows.value.length>=32)return;selectedPeriod.value={id:newFunction().id,config:{totalInput:'',usageDay:false,usageMonth:false}};tableError.value=''}
function savePeriod(config:PeriodUsageDraft){const original=selectedPeriod.value;if(props.disabled||unavailable.value||!original||!coordinateAvailable.value)return;const values=props.propertyOperations?.operations??functionsToPropertyOperations(props.modelValue),row:PropertyOperationDraft={id:original.id,kind:'PERIOD_USAGE',config},exists=values.some(item=>item.id===original.id);if(commitOperations(exists?values.map(item=>item.id===original.id?row:item):[...values,row])){if(props.detail)emit('commit');else selectedPeriod.value=undefined}}
function openGeofence(kind:GeofenceKind){if(blocked.value||!coordinateAvailable.value||rows.value.length>=32)return;selectedGeofence.value={id:newFunction().id,kind,config:kind==='POINT_IN_CIRCLE'?{point:'',circle:'',result:''}:{point:'',polygon:'',result:''}};tableError.value=''}
function saveGeofence(config:GeofenceDraft){const original=selectedGeofence.value;if(props.disabled||unavailable.value||!original||!coordinateAvailable.value)return;const values=props.propertyOperations?.operations??functionsToPropertyOperations(props.modelValue),row:PropertyOperationDraft=original.kind==='POINT_IN_CIRCLE'?{id:original.id,kind:original.kind,config:config as CircleGeofenceDraft}:{id:original.id,kind:original.kind,config:config as PolygonGeofenceDraft},exists=values.some(item=>item.id===original.id);if(commitOperations(exists?values.map(item=>item.id===original.id?row:item):[...values,row])){if(props.detail)emit('commit');else selectedGeofence.value=undefined}}
function commitOperations(operations:PropertyOperationDraft[]){try{const value:PropertyOperationsDraft={profile:'PROPERTY_TRANSFORM_V1',operations};emit('update:propertyOperations',operations.length?propertyOperationsDraft(value):clonePropertyOperations(value));tableError.value='';return true}catch(cause){tableError.value=cause instanceof Error?cause.message:'请补全预处理操作';return false}}
function saveOperation(value:FunctionDraft){
 const original=selected.value;if(props.disabled||unavailable.value||!original||value.id!==original.id||value.format!==original.format)return
 if(props.propertyOperations){const row:PropertyOperationDraft={id:value.id,kind:'FUNCTION',function:{format:value.format,source:value.source}},exists=props.propertyOperations.operations.some(item=>item.id===value.id);if(commitOperations(exists?props.propertyOperations.operations.map(item=>item.id===value.id?row:item):[...props.propertyOperations.operations,row])){if(props.detail)emit('commit');else selected.value=undefined};return}
 const exists=props.modelValue.some(row=>row.id===value.id),values=exists?props.modelValue.map(row=>row.id===value.id?value:row):[...props.modelValue,value];if(values.reduce((sum,row)=>sum+new TextEncoder().encode(row.source).length,0)>65536){tableError.value='操作函数总内容超过允许大小';return}emit('update:modelValue',values);if(props.detail)emit('commit');else selected.value=undefined
}
function saveCoordinate(config:CoordinateTransformDraft){const original=selectedCoordinate.value;if(props.disabled||unavailable.value||!original||!coordinateAvailable.value)return;const values=props.propertyOperations?.operations??functionsToPropertyOperations(props.modelValue),row:PropertyOperationDraft={id:original.id,kind:'COORDINATE_TRANSFORM',config},exists=values.some(item=>item.id===original.id);if(commitOperations(exists?values.map(item=>item.id===original.id?row:item):[...values,row])){if(props.detail)emit('commit');else selectedCoordinate.value=undefined}}
function denied(cause:ApiError){selected.value=undefined;selectedCoordinate.value=undefined;selectedGeofence.value=undefined;selectedPeriod.value=undefined;pickerShown.value=false;removal.value=undefined;sorting.value=false;unavailable.value=true;tableError.value='当前权限已变化，请重新读取规则。';emit('denied',cause)}
function changedRows(values:(FunctionDraft|PropertyOperationDraft)[]){if(props.propertyOperations)commitOperations(values as PropertyOperationDraft[]);else emit('update:modelValue',values as FunctionDraft[])}
function tableMove(id:string,direction:-1|1){if(props.disabled||unavailable.value||!sorting.value)return;const index=rows.value.findIndex(row=>row.id===id),target=index+direction;if(index<0||target<0||target>=rows.value.length)return;const values=[...rows.value];[values[index],values[target]]=[values[target]!,values[index]!];changedRows(values)}
function reorder(from:string,to:string){if(props.disabled||unavailable.value||!sorting.value)return;const values=[...rows.value],a=values.findIndex(row=>row.id===from),b=values.findIndex(row=>row.id===to);if(a<0||b<0||a===b)return;const [row]=values.splice(a,1);values.splice(b,0,row!);changedRows(values)}
function cancelCommand(){if(props.disabled||props.recoveryPending)return;selected.value=undefined;selectedCoordinate.value=undefined;selectedGeofence.value=undefined;selectedPeriod.value=undefined;pickerShown.value=false;removal.value=undefined;sorting.value=false;tableError.value='';if(props.detail)emit('cancelCommand')}
function sort(value:boolean){if(props.disabled||unavailable.value)return;if(value)sorting.value=true;else if(props.detail)emit('commit');else sorting.value=false}
function confirmRemoval(){if(props.disabled||!removal.value)return;if(rows.value.length<=1){tableError.value='请至少保留1项预处理操作，当前操作尚未移除。';return}const values=rows.value.filter(row=>row.id!==removal.value);changedRows(values);emit('commit')}
watch(()=>props.command,value=>{if(!props.detail||!value||props.disabled||unavailable.value||busy.value)return;if(value.kind==='ADD')addOperation();else if(value.kind==='SORT')sorting.value=true;else if('index' in value){const row=rows.value[value.index];if(!row)return;if(value.kind==='EDIT')open(row.id);else remove(row.id)}},{immediate:true})
</script>
<template><section class="preprocess-functions-editor">
 <template v-if="!dataReport"><RulePreprocessOperationTable v-if="!unavailable" :model-value="rows" :detail="detail" :recovery-pending="recoveryPending" :recovering="recovering" @recover="emit('recover')" :disabled="disabled||!!selected||!!selectedCoordinate||!!selectedGeofence||!!selectedPeriod||pickerShown||!!removal" :hide-add="hideAdd" :sorting="sorting" @add="addOperation" @edit="open" @format="setFormat" @remove="remove" @move="tableMove" @reorder="reorder" @sort="sort" @cancel-sort="cancelCommand"/><el-alert v-if="tableError" :title="tableError" type="error" :closable="false"/><el-dialog v-if="pickerShown" :model-value="true" title="添加操作" width="min(800px,94vw)" :lock-scroll="false" :close-on-click-modal="false" :before-close="closePicker" append-to-body><el-form :disabled="false"><div class="property-action-options"><el-button class="property-action-option" data-preprocess-choice="FUNCTION" :disabled="disabled" @click="chooseOperation('FUNCTION')"><ReferenceIcon glyph="󰡱"/><span><strong>预处理函数</strong><small>{{kind==='ATTRS_PUSH_PREPROC'?'可对属性下发进行预处理，比如将属性值转换为硬件设备可读的格式。':'可对属性上报后进行自定义预处理，比如将某些属性转化为更适合可视化图表的属性值。'}}</small></span></el-button><el-button v-if="coordinateAvailable" class="property-action-option" data-preprocess-choice="COORDINATE_TRANSFORM" :disabled="disabled" @click="chooseOperation('COORDINATE_TRANSFORM')"><ReferenceIcon glyph="󰍏"/><span><strong>GPS 位置坐标系转换</strong><small>将 GPS 的 WGS84 原始坐标位置，转换成国内地图服务商支持的坐标体系，支持百度地图、高德地图、腾讯地图、搜狗地图等。</small></span></el-button><el-button v-if="coordinateAvailable" class="property-action-option" data-preprocess-choice="POINT_IN_CIRCLE" :disabled="disabled" @click="chooseOperation('POINT_IN_CIRCLE')"><ReferenceIcon glyph="󱋼"/><span><strong>GPS 位置电子围栏检查（圆形）</strong><small>检查 GPS 位置是否处于电子围栏中，支持圆形围栏。</small></span></el-button><el-button v-if="coordinateAvailable" class="property-action-option" data-preprocess-choice="POINT_IN_POLYGON" :disabled="disabled" @click="chooseOperation('POINT_IN_POLYGON')"><ReferenceIcon glyph="󱋼"/><span><strong>GPS 位置电子围栏检查（多边形）</strong><small>检查 GPS 位置是否处于电子围栏中，支持多边形围栏。</small></span></el-button><el-button v-if="coordinateAvailable" class="property-action-option" data-preprocess-choice="PERIOD_USAGE" :disabled="disabled" @click="chooseOperation('PERIOD_USAGE')"><ReferenceIcon glyph="󰓅"/><span><strong>计算抄表周期累计值</strong><small>通过电表/水表上报的总累计值，实时生成当日、当月的周期累计值。</small></span></el-button></div></el-form><template #footer><el-form :disabled="false"><el-button :disabled="disabled" @click="closePicker">取消</el-button></el-form></template></el-dialog><RulePreprocessFunctionDialog v-if="selected" :model-value="selected" :kind="kind" :project-id="projectId" :source-limit="sourceLimit" :validation-error="tableError||requestError" :top="detail?'10vh':undefined" :recovery-pending="recoveryPending" :recovering="recovering" @recover="emit('recover')" :disabled="disabled" @save="saveOperation" @cancel="cancelCommand" @denied="denied"/><RuleCoordinateTransformDialog v-if="selectedCoordinate&&source&&projectId" :project-id="projectId" :source="source" :draft="selectedCoordinate.config" :validation-error="tableError||requestError" :top="detail?'10vh':undefined" :recovery-pending="recoveryPending" :recovering="recovering" @recover="emit('recover')" :disabled="disabled" @save="saveCoordinate" @cancel="cancelCommand" @denied="denied"/><RuleGeofenceDialog v-if="selectedGeofence&&source&&projectId" :project-id="projectId" :source="source" :kind="selectedGeofence.kind" :draft="selectedGeofence.config" :disabled="disabled" :validation-error="tableError||requestError" :top="detail?'10vh':undefined" :recovery-pending="recoveryPending" :recovering="recovering" @recover="emit('recover')" @save="saveGeofence" @cancel="cancelCommand" @denied="denied"/><RulePeriodUsageDialog v-if="selectedPeriod&&source&&projectId" :project-id="projectId" :source="source" :draft="selectedPeriod.config" :disabled="disabled" :validation-error="tableError||requestError" :top="detail?'10vh':undefined" :recovery-pending="recoveryPending" :recovering="recovering" @recover="emit('recover')" @save="savePeriod" @cancel="cancelCommand" @denied="denied"/><el-dialog v-if="removal" :model-value="true" title="提示" width="500px" :lock-scroll="false" :close-on-click-modal="false" :close-on-press-escape="!disabled" :show-close="!disabled" :before-close="cancelCommand" append-to-body><div class="operation-removal-prompt"><el-icon aria-hidden="true"><WarningFilled/></el-icon><span>确认移除该操作吗？</span></div><el-alert v-if="tableError||requestError" :title="tableError||requestError" type="warning" :closable="false"/><template #footer><el-form :disabled="false"><el-button v-if="recoveryPending" :disabled="recovering" @click="emit('recover')">读取核对</el-button><el-button :disabled="disabled" @click="cancelCommand">取消</el-button><el-button type="primary" :disabled="disabled" @click="confirmRemoval">确定</el-button></el-form></template></el-dialog></template>
 <template v-else>
 <template v-if="dataReport"><p class="function-help">属性解析函数接收(identifier, data)，返回属性对象；identifier为所选数据流标识，可选第三参数options={}；带参数Topic的运行通过options.params读取本条上报的参数，参数不代表设备身份。</p><p v-if="dataFormat==='TEXT'" class="function-help">TEXT：使用data.toString()或data.toString('utf8')读取文本。</p><template v-else><p class="function-help">HEX/JSON：使用data.length、data[i]读取原字节；readInt8 / readUInt8读取8位整数，readInt16 / readUInt16 / readInt32 / readUInt32配合BE或LE读取大端或小端整数，readFloatBE / readFloatLE读取32位浮点数。offset省略时为0，指定时须为范围内整数。toString() / toString('utf8')严格读取UTF8，toString('hex') / toString('base64')编码原字节。Cloud.validateCrc16Modbus(data)校验完整帧，Cloud.jsonParse(text)解析JSON文本。Cloud.Utils提供JSON编解码与类型判断、GB2312/GBK文本转换、8位转换、UTF8/HEX/Base64字符串与只读字节对象转换，以及8/16/32位整数、32/64位浮点数的ToHex编码，适用的ToHexLE方法使用小端；位数组高位在前。Cloud.ModbusRTU可生成带CRC的请求帧，由下行操作决定是否发送。</p><p class="function-help">仅提供上述方法。越界、非法编码、非有限输出或输入超过函数64KiB预算时解析失败；不会改写原数据。</p></template></template><p v-else class="function-help">操作按从上到下的顺序处理本次属性。</p>
 <p v-if="!modelValue.length" class="empty-actions">尚未添加预处理操作</p>
 <section v-for="(operation,index) in modelValue" :key="operation.id" class="preprocess-operation" :data-function-id="operation.id">
  <div class="operation-heading"><strong>{{index+1}}. {{dataReport?'DATA属性解析函数':'属性预处理函数'}}</strong><span><el-button text :disabled="blocked||index===0" :aria-label="'上移操作 '+(index+1)" @click="move(index,-1)">上移</el-button><el-button text :disabled="blocked||index===modelValue.length-1" :aria-label="'下移操作 '+(index+1)" @click="move(index,1)">下移</el-button><el-button text :disabled="blocked" :aria-label="'移除操作 '+(index+1)" @click="remove(operation.id)">移除</el-button></span></div>
  <p v-if="dataReport">CommonJS（module.exports）</p><el-form-item v-else label="函数格式"><el-select :model-value="operation.format" :disabled="blocked" :aria-label="'操作 '+(index+1)+' 函数格式'" @update:model-value="update(index,{format:$event})"><el-option label="CommonJS（module.exports）" value="COMMON_JS"/><el-option label="函数表达式" value="FUNCTION_EXPRESSION"/></el-select></el-form-item>
  <el-form-item label="函数源码"><RuleFunctionCodeEditor v-if="operation.format==='COMMON_JS'" :model-value="operation.source" :disabled="disabled" :ariaLabel="'操作 '+(index+1)+' 函数源码'" @update:model-value="update(index,{source:$event})" @busy="formatBusy(operation.id,$event)"/><el-input v-else class="legacy-function-source" :model-value="operation.source" :disabled="blocked" :aria-label="'操作 '+(index+1)+' 函数源码'" type="textarea" :rows="7" :placeholder="placeholder" @update:model-value="update(index,{source:$event})"/></el-form-item>
 </section>
 <el-button v-if="!hideAdd" :disabled="blocked||modelValue.length>=(dataReport?1:32)" @click="add">添加操作</el-button><span class="source-budget" :class="{over:bytes>65536}">{{bytes}} / 65536 UTF8字节</span>
</template></section></template>
<style scoped>.operation-removal-prompt{display:flex;align-items:center;gap:12px;line-height:24px}.operation-removal-prompt .el-icon{flex:none;font-size:24px;color:var(--el-color-warning)}
.preprocess-functions-editor{min-width:0}.property-action-options{display:flex;flex-direction:column;gap:14px}.property-action-option{display:flex;align-items:center;justify-content:flex-start;text-align:left;white-space:normal;width:100%;height:auto;min-height:76px;padding:18px 20px;margin-left:0}.property-action-option>.reference-icon{font-size:24px;margin-right:20px}.property-action-option :deep(>span){display:flex;align-items:center;gap:20px}.property-action-option strong{display:block;font-size:14px;font-weight:400;color:#303133;line-height:22px}.property-action-option small{display:block;font-size:13px;font-weight:400;color:#909399;line-height:20px;margin-top:5px}.function-help,.empty-actions{font-size:13px;color:var(--el-text-color-secondary)}.empty-actions{padding:16px 0}.preprocess-operation{border-top:1px solid var(--el-border-color-lighter);margin:18px 0;padding-top:12px}.operation-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:12px}.operation-heading strong{font-size:14px;font-weight:500}.operation-heading .el-button+.el-button{margin-left:0}.preprocess-operation .el-form-item{margin-bottom:14px}.preprocess-operation :deep(.el-select){width:260px;max-width:100%}.legacy-function-source :deep(textarea){font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:13px;line-height:1.6}.source-budget{font-size:12px;color:var(--el-text-color-secondary);margin-left:12px}.source-budget.over{color:var(--el-color-danger)}@media(max-width:560px){.operation-heading{display:block}.operation-heading>span{display:flex;justify-content:flex-end}.source-budget{display:block;margin:8px 0}}
</style>
